import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import Link from 'next/link';

import styles from '@/components/builder/editor.module.css';
import { SiteMap, type MapPage } from '@/components/builder/SiteMap';
import { getStorefrontUrl } from '@/lib/builder/config';

export const dynamic = 'force-dynamic';

/**
 * The way in: the site itself, as something to point at.
 *
 * The map is generated by `npm run builder:capture` and committed, so this screen
 * needs no browser at request time. When it is missing — a fresh checkout, or
 * before the first capture — the older list of sections is shown instead, so
 * the tool is never unusable.
 */
function loadMap(): MapPage[] {
  const path = resolve(process.cwd(), 'public/builder/previews/map.json');
  if (!existsSync(path)) return [];
  try {
    return JSON.parse(readFileSync(path, 'utf8')) as MapPage[];
  } catch {
    return [];
  }
}

export default function Dashboard() {
  const storefrontUrl = getStorefrontUrl();
  const pages = loadMap();

  return (
    <>
      <h1 className={styles.pageTitle}>O que queres mudar?</h1>
      <p className={styles.pageIntro}>
        Carrega na parte do site que queres alterar. Depois de publicares, o site actualiza sozinho
        pouco depois.
      </p>

      <SiteMap pages={pages} storefrontUrl={storefrontUrl} />

      <Link className={styles.listLink} href="/builder/secoes">
        Preferes uma lista? Ver todas as secções →
      </Link>
    </>
  );
}
